    coreValuesSub: { en: "The principles that guide every seed we plant and every box we deliver.", rw: "Ayo ni mategeko agenga buri mbuto tuziba no gutunga buri sashi dutanga.", fr: "Les principes qui guident chaque graine plantée et chaque livraison.", sw: "Kanuni zinazoongoza kila mbegu tunayopanda na kila kisanduku." },
    val1Title: { en: "Certified Organic", rw: "Byemejwe Kamere", fr: "Bio Certifié", sw: "Organiki Iliothibitishwa" },
    val1Desc: { en: "We follow strict organic standards, ensuring no chemical pesticides or fertilizers ever touch our soil.", rw: "Tugenda ukurikira amategeko y'ibiribwa kamere, nta pesitisidi igera ku butaka bwacu.", fr: "Nous suivons des normes biologiques strictes, garantissant que jamais de pesticides chimiques ne touchent notre sol.", sw: "Tunafuata viwango vikali vya organiki, kuhakikisha hakuna dawa za kemikali zinaigusa udongo." },
    val2Title: { en: "Fair For Farmers", rw: "Ukuri kuri Abahinzi", fr: "Équitable pour les Agriculteurs", sw: "Haki kwa Wakulima" },
    val2Desc: { en: "By cutting out middle-men, we ensure our farmers get paid fairly for their hard work and dedication.", rw: "Tuvanye interineti hagati kugira ngo abahinzi bacu baishyurwe neza.", fr: "En éliminant les intermédiaires, nous veillons à ce que nos agriculteurs soient rémunérés équitablement.", sw: "Kwa kuondoa waaana, tunahakikisha wakulima wetu analipwa kwa usawa." },
    val3Title: { en: "Health First", rw: "Ubuzima Bwambere", fr: "Santé d'Abord", sw: "Afya Kwanza" },
    val3Desc: { en: "Your health is our priority. Fresh produce is harvested and delivered within 24 hours for maximum nutrients.", rw: "Ubuzima bwawe ni inshingano yacu. Ibibiri bivanwa kandi biragezwa mu masaha 24.", fr: "Votre santé est notre priorité. Les produits frais sont récoltés et livrés en 24h.", sw: "Afya yako ni kipaumbele chetu. Mazao mapya huvunwa na kukabidhi ndani ya masaa 24." },
    teamTitle: { en: "The People Behind The Produce", rw: "Abantu babiri inyuma", fr: "Les Personnes Derrière les Produits", sw: "Watu Nyuma ya Mazao" },
    teamSub: { en: "Expert cultivators, logistics masters, and quality enthusiasts.", rw: "Inzobere z'ubuhinzi, iy'ubutoranyi, n'abakunda ubwiza.", fr: "Cultivateurs experts, maîtres logistiques et passionnés de qualité.", sw: "Wataalamu wa kilimo, mabingwa wa usafirishaji, na wapenda ubora." },
